//
// TiffImage.hpp
// =============
// This file contains the TiffImage class and related functionality. This class
// holds TIFF image metadata and provides access to the image structure and
// pixel data. No functionality for manipulating or interpreting the image data
// is provided here.
//
// A program like the following could be used for loading a TIFF image with your
// custom processing:
//
//     #include <tiffcraft/TiffImage.hpp>
//     #include <iostream>
//
//     int main() {
//       TiffCraft::load("image.tiff",
//         [](const TiffCraft::TiffImage::Header& header,
//            const TiffCraft::TiffImage::IFD& ifd,
//            TiffCraft::TiffImage::ImageData imageData) {
//           std::cout << "Loaded IFD with " << ifd.entries().size()
//                     << " entries." << std::endl;
//           std::cout << "Image data size: " << imageData.size() << std::endl;
//
//           // Add your own image processing code here
//
//         });
//
//       return 0;
//     }
//

#pragma once

#include <type_traits>
#include <functional>
#include <stdexcept>
#include <optional>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <cassert>
#include <memory>
#include <string>
#include <vector>
#include <span>
#include <map>
#include <set>
#include <bit>

#if __cpp_lib_byteswap >= 201806L
# include <bit> // C++23 byteswap
#else
# include <algorithm>
namespace std {
  template <typename T>
  T byteswap(T value) {
    static_assert(std::is_trivially_copyable_v<T>, "Type must be trivially copyable");
    T result;
    std::reverse_copy(reinterpret_cast<const char*>(&value),
                      reinterpret_cast<const char*>(&value) + sizeof(T),
                      reinterpret_cast<char*>(&result));
    return result;
  }
}
#endif

namespace TiffCraft {

  // TiffCraft version
  constexpr int MAJOR_VERSION = 0;
  constexpr int MINOR_VERSION = 2;
  constexpr int PATCH_VERSION = 0;

  inline std::string version() {
    return std::to_string(MAJOR_VERSION)
      + "." + std::to_string(MINOR_VERSION)
      + "." + std::to_string(PATCH_VERSION);
  }

  // TIFF known tags
  // ===============
  // The enum provides a list of known TIFF tags for easy access and display.
  // Those tags not included in this list can still be accessed by their
  // numerical value.
  enum class Tag : uint16_t {
    // Image File Directory (IFD) tags
    Null = 0x0000, // Not a real tag, used for padding or as a placeholder
    NewSubfileType = 0x00FE,
    SubfileType = 0x00FF,
